<template><section class="space-y-5"><div class="flex items-end justify-between"><div><p class="text-xs uppercase tracking-wider text-indigo-400">Price watch</p><h1 class="mt-1 text-2xl font-bold text-white">Ideal list</h1></div><NuxtLink to="/market/marketplace" class="btn-primary">Browse marketplace</NuxtLink></div><div v-for="item in items" :key="item.id" class="pc-card flex flex-wrap items-center justify-between gap-4"><div><h2 class="font-semibold text-white">{{ item.listing.title }}</h2><p class="mt-1 text-xs text-slate-500">Current {{ money(item.listing.price_minor, item.listing.currency) }} · Target {{ money(item.target_price_minor, item.currency) }}</p></div><button class="btn-secondary" @click="remove(item.id)">Remove</button></div><p v-if="!items.length && !error" class="pc-card text-sm text-slate-400">No watched listings yet. Add one from the public marketplace.</p><p v-if="error" class="pc-card text-red-300">{{ error }}</p></section></template>
<script setup lang="ts">definePageMeta({ layout: 'procurement', middleware: ['auth'], alias: ['/buyer/ideal-list'] }); const api = useCommerce(); const items = ref<any[]>([]); const error = ref(''); const money = (value?: number, currency = 'EUR') => value == null ? '—' : new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); async function load() { items.value = (await api.listWatchlist()).items } async function remove(id: string) { await api.removeWatchlist(id); await load() } onMounted(async () => { try { await load() } catch (e: any) { error.value = e?.data?.detail || e?.message } })</script>
